<?php

declare(strict_types=1);

namespace Tests\Feature;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\TestCase;

/**
 * general-styles.css and mobile-touch.css were split into per-concern parts
 * (microweber/general/*.css and microweber/mobile/*.css) for editability. The
 * monolith files are kept as GENERATED byte-for-byte concatenations of their
 * parts (sorted), because microweber/index.css still @imports them and ~80
 * contract tests read their bytes. build.cjs (regenerateSplitMonoliths) rebuilds
 * the monolith from the parts before every bundle build.
 *
 * This test pins that the committed monolith equals concat(sorted parts) so the
 * two representations can never silently drift. If it fails: you edited the
 * monolith directly (edit the PARTS instead) or forgot to regenerate — run
 * `cd packages/microweber-filament-theme && npm run build` (or concatenate the
 * sorted parts) to resync.
 */
class ThemeCssSplitMonolithDriftContractTest extends TestCase
{
    private const BASE = 'packages/microweber-filament-theme/resources/assets/css/microweber';

    public static function monolithProvider(): array
    {
        return [
            'general-styles.css'       => ['general', 'general-styles.css'],
            'mobile-touch.css'         => ['mobile', 'mobile-touch.css'],
            'element-style-editor.css' => ['ese', 'element-style-editor.css'],
            'live-edit-classes.css'    => ['live-edit', 'live-edit-classes.css'],
        ];
    }

    #[Test]
    #[DataProvider('monolithProvider')]
    public function monolith_equals_byte_for_byte_concatenation_of_its_parts(string $dir, string $monolith): void
    {
        $base = base_path(self::BASE);

        $parts = glob($base . '/' . $dir . '/*.css');
        sort($parts);
        $this->assertNotEmpty($parts, "No split parts found in microweber/$dir/ — the split directory is missing.");

        $concat = '';
        foreach ($parts as $p) {
            $concat .= file_get_contents($p);
        }

        $actual = file_get_contents($base . '/' . $monolith);

        $this->assertSame(
            $concat,
            $actual,
            "$monolith must be the byte-for-byte concatenation of the sorted microweber/$dir/*.css parts. "
            . "Edit the PARTS, then run `npm run build` (build.cjs regenerates the monolith) to resync."
        );
    }
}
